std::filesystem::path filesystem_path(const QString& path) {
    return std::filesystem::path(path.toStdWString());
}

bool same_filesystem_path(const std::filesystem::path& left,
                          const std::filesystem::path& right) {
    const auto normalized_left = left.lexically_normal();
    const auto normalized_right = right.lexically_normal();
#ifdef _WIN32
    return QString::fromStdWString(normalized_left.wstring()).compare(
               QString::fromStdWString(normalized_right.wstring()), Qt::CaseInsensitive) == 0;
#else
    return normalized_left == normalized_right;
#endif
}

bool has_entity(const Document& document, const QString& entity_id) {
    const auto snapshot = document.snapshot();
    return snapshot.entities().contains(entity_id.toStdString());
}

constexpr int visibility_type_role = Qt::UserRole + 1;
constexpr int symbol_family_role = Qt::UserRole + 2;

bool is_visibility_container_type(std::string_view type) {
    return type == "floor" || type == "layer";
}

bool is_visibility_container_item(const QTreeWidgetItem* item) {
    if (item == nullptr) {
        return false;
    }
    const auto type = item->data(0, visibility_type_role).toString();
    return type == QStringLiteral("floor") || type == QStringLiteral("layer");
}

// QTreeWidget changes the current item while it handles a mouse press on a
// check indicator. Keep that interaction distinguishable from a normal row
// click without relying on the global cursor position (or on a stale deferred
// event). The base widget still owns all selection and keyboard behavior.
class SymbolLibraryList final : public QListWidget {
public:
    using QListWidget::QListWidget;
protected:
    void startDrag(Qt::DropActions) override {
        if (!currentItem()) return;
        const auto id = currentItem()->data(Qt::UserRole).toString();
        if (id.isEmpty()) return;
        auto* mime = new QMimeData;
        mime->setData("application/x-vertex-symbol", QByteArray::fromStdString(
            json{{"id", id.toStdString()}, {"scale", property("symbolScale").toDouble()}}.dump()));
        QDrag drag(this);
        drag.setMimeData(mime);
        const auto ghost = currentItem()->icon().pixmap(64, 64);
        drag.setPixmap(ghost);
        drag.setHotSpot(QPoint(32, 32));
        drag.exec(Qt::CopyAction);
    }
};

class VisibilityEyeDelegate final : public QStyledItemDelegate {
public:
    using QStyledItemDelegate::QStyledItemDelegate;
    void paint(QPainter* painter, const QStyleOptionViewItem& option,
               const QModelIndex& index) const override {
        QStyleOptionViewItem styled(option);
        initStyleOption(&styled, index);
        if (!(styled.features & QStyleOptionViewItem::HasCheckIndicator)) {
            QStyledItemDelegate::paint(painter, option, index);
            return;
        }
        auto* style = styled.widget ? styled.widget->style() : QApplication::style();
        const auto rect = style->subElementRect(QStyle::SE_ItemViewItemCheckIndicator,
                                               &styled, styled.widget);
        // Retain Qt's check-state semantics and keyboard hit target, but draw
        // a visibility eye instead of a form checkbox.
        QStyledItemDelegate::paint(painter, option, index);
        painter->save();
        const bool selected = styled.state & QStyle::State_Selected;
        painter->fillRect(rect.adjusted(-1, -1, 1, 1), styled.palette.brush(
            selected ? QPalette::Highlight : QPalette::Base));
        painter->setPen(QPen(styled.palette.color(selected ? QPalette::HighlightedText : QPalette::Text), 1.3));
        painter->setBrush(Qt::NoBrush);
        const auto eye = QRectF(rect).adjusted(1, 3, -1, -3);
        painter->drawEllipse(eye);
        painter->drawEllipse(eye.center(), 1.7, 1.7);
        if (styled.checkState != Qt::Checked)
            painter->drawLine(rect.topLeft() + QPoint(1, 1), rect.bottomRight() - QPoint(1, 1));
        painter->restore();
    }
};

class VisibilityTreeWidget final : public QTreeWidget {
public:
    using QTreeWidget::QTreeWidget;

    [[nodiscard]] bool checkboxInteraction() const noexcept {
        return m_checkbox_interaction;
    }

protected:
    void mousePressEvent(QMouseEvent* event) override {
        m_checkbox_interaction = false;
        if (event != nullptr) {
            auto* item = itemAt(event->position().toPoint());
            if (item != nullptr && is_visibility_container_item(item)) {
                QStyleOptionViewItem option;
                option.initFrom(this);
                option.index = indexFromItem(item, 0);
                option.rect = visualItemRect(item);
                option.state |= QStyle::State_Enabled;
                option.features |= QStyleOptionViewItem::HasCheckIndicator;
                option.checkState = item->checkState(0);
                const auto indicator = style()->subElementRect(
                    QStyle::SE_ItemViewItemCheckIndicator, &option, this);
                m_checkbox_interaction = indicator.contains(event->position().toPoint());
                if (m_checkbox_interaction) {
                    // Handle the small checkbox hit target explicitly. Fusion
                    // styles can otherwise let a press/release pair fall
                    // through to row selection when a rounded item stylesheet
                    // changes the delegate's geometry.
                    item->setCheckState(0, item->checkState(0) == Qt::Checked
                                               ? Qt::Unchecked : Qt::Checked);
                    event->accept();
                    return;
                }
            }
        }
        QTreeWidget::mousePressEvent(event);
    }

    void mouseReleaseEvent(QMouseEvent* event) override {
        if (m_checkbox_interaction) {
            if (event != nullptr) event->accept();
            m_checkbox_interaction = false;
            return;
        }
        QTreeWidget::mouseReleaseEvent(event);
        m_checkbox_interaction = false;
    }

private:
    bool m_checkbox_interaction{false};
};

void ensure_project_scaffold(Document& document) {
    if (!document.snapshot().entities().empty()) {
        return;
    }
    document.apply(ApplyEntityChanges{
        .expected_revision = document.revision(),
        .entity_changes = {
            EntityChange::upsert(Entity{"property-1",
                                        "property",
                                        json{{"name", "Untitled property"},
                                             {"subject", json{{"name", "Untitled property"},
                                                               {"address", ""},
                                                               {"reference", ""},
                                                               {"attributes", json::object()}}},
                                             {"calculation_workflow", "measurement"},
                                             {"calculation_profile",
                                              calculation_profile_json(default_calculation_profile())}},
                                        false,
                                        json::object()}),
            EntityChange::upsert(Entity{"building-1",
                                        "building",
                                        json{{"property_id", "property-1"},
                                             {"name", "Building 1"}},
                                        false,
                                        json::object()}),
            EntityChange::upsert(Entity{"floor-1",
                                        "floor",
                                        json{{"building_id", "building-1"},
                                             {"property_id", "property-1"},
                                             {"name", "Floor 1"},
                                             {"elevation_m", 0.0}},
                                        false,
                                        json::object()}),
            EntityChange::upsert(Entity{"layer-1",
                                        "layer",
                                        json{{"floor_id", "floor-1"},
                                             {"name", "Default layer"}},
                                        false,
                                        json::object()}),
            EntityChange::upsert(make_sheet_view_entity("sheet-view-1", default_sheet_view_model())),
            EntityChange::upsert(make_annotation_entity("annotations-1", AnnotationState{})),
        },
        .message = "create project scaffold",
    });
}

// Keep the actually submitted metre literals for the legacy layer-input API.
// A DOM round trip could replace decimal input with its rounded binary value.
class SlabLayerQuantityTokens final : public nlohmann::json_sax<json> {
public:
    std::vector<std::string> thickness_inputs;
    bool null() override { return scalar(); }
    bool boolean(bool) override { return scalar(); }
    bool number_integer(number_integer_t value) override { return number(std::to_string(value)); }
    bool number_unsigned(number_unsigned_t value) override { return number(std::to_string(value)); }
    bool number_float(number_float_t value, const string_t& literal) override {
        if (!std::isfinite(value)) throw std::invalid_argument("Layer input must be finite.");
        return number(literal);
    }
    bool string(string_t& value) override { charge(value); return scalar(); }
    bool binary(binary_t&) override { return false; }
    bool start_object(std::size_t) override {
        if (frames.size() == 1 && frames.front().array) {
            if (thickness_inputs.size() >= 1024) throw std::invalid_argument("Layer count exceeds 1024.");
            thickness_inputs.emplace_back();
        }
        return start(false);
    }
    bool start_array(std::size_t) override { return start(true); }
    bool key(string_t& value) override {
        charge(value);
        if (frames.empty() || frames.back().array || !frames.back().keys.insert(value).second)
            throw std::invalid_argument("Layer input contains a duplicate or misplaced key.");
        frames.back().key = value;
        return true;
    }
    bool end_object() override { frames.pop_back(); return true; }
    bool end_array() override { frames.pop_back(); return true; }
    bool parse_error(std::size_t, const std::string&, const nlohmann::detail::exception&) override { return false; }
private:
    struct Frame { bool array{}; std::string key; std::set<std::string, std::less<>> keys; };
    std::vector<Frame> frames;
    std::size_t nodes{}, bytes{};
    void charge(const std::string& value) {
        if (value.size() > 1024 * 1024 - bytes) throw std::invalid_argument("Layer input string budget exceeded.");
        bytes += value.size();
    }
    bool scalar() {
        if (++nodes > 65536) throw std::invalid_argument("Layer input value budget exceeded.");
        return true;
    }
    bool start(bool array) {
        if (frames.size() >= 32) throw std::invalid_argument("Layer input nesting budget exceeded.");
        scalar(); frames.push_back(Frame{array, {}, {}}); return true;
    }
    bool number(const std::string& literal) {
        charge(literal);
        if (frames.size() == 2 && frames.front().array && !frames.back().array &&
            frames.back().key == "thickness_m") thickness_inputs.back() = literal;
        return scalar();
    }
};

bool is_building_quantity_path(const std::string& pointer) {
    for (const auto* scalar : {"/width_m", "/depth_m", "/height_m", "/radius_m", "/total_rise_m",
             "/going_m", "/run_m", "/span_m", "/rise_m", "/overhang_m", "/thickness_m", "/length_m",
             "/post_spacing_m", "/top_landing/depth_m", "/top_landing/thickness_m"})
        if (pointer == scalar) return true;
    for (const std::string_view prefix : {"/landings/", "/flights/"}) {
        if (!pointer.starts_with(prefix)) continue;
        const auto separator = pointer.find('/', prefix.size());
        if (separator != std::string::npos) {
            const auto index = pointer.substr(prefix.size(), separator - prefix.size());
            std::size_t row{};
            const auto [end, error] = std::from_chars(index.data(), index.data() + index.size(), row);
            const auto key = pointer.substr(separator + 1);
            const bool dimension = prefix == "/flights/" ? key == "going_m" || key == "width_m"
                : key == "depth_m" || key == "thickness_m" || key == "return_gap_m";
            if (!index.empty() && (index.size() == 1 || index.front() != '0') &&
                error == std::errc{} && end == index.data() + index.size() && row < 256 &&
                dimension) return true;
        }
    }
    for (const auto* vector : {"/base_center_m/", "/base_position_m/", "/start_m/", "/end_m/"}) {
        const std::string_view prefix(vector);
        if (pointer.starts_with(prefix) && pointer.size() == prefix.size() + 1 &&
            pointer.back() >= '0' && pointer.back() <= '2') return true;
    }
    return false;
}

bool quantity_entry_matches(const json& receipt, const json& properties, const std::string& pointer) {
    try {
        if (!is_building_quantity_path(pointer)) return false;
        if (!receipt.is_object() || !receipt.contains("version") ||
            !receipt.at("version").is_number_integer() || receipt.at("version") != 1 ||
            !receipt.at("original_expression").is_string() || !receipt.at("entered_unit").is_string())
            return false;
        const auto unit_name = receipt.at("entered_unit").get<std::string>();
        const std::map<std::string, Unit> units{{"m", Unit::metre}, {"mm", Unit::millimetre},
            {"cm", Unit::centimetre}, {"ft", Unit::foot}, {"in", Unit::inch}};
        const auto unit = units.find(unit_name);
        if (unit == units.end()) return false;
        const auto quantity = parse_quantity(receipt.at("original_expression").get<std::string>(), unit->second);
        const auto& rational = receipt.at("exact_metres");
        const auto& value = properties.at(json::json_pointer(pointer));
        const auto exact_integer = [](const json& item, std::int64_t expected) {
            return item.is_number_integer() &&
                (!item.is_number_unsigned() || item.get<std::uint64_t>() <=
                    static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max())) &&
                item.get<std::int64_t>() == expected;
        };
        return rational.is_object() &&
            exact_integer(rational.at("numerator"), quantity.exact_metres.numerator) &&
            exact_integer(rational.at("denominator"), quantity.exact_metres.denominator) &&
            quantity.entered_unit == unit->second && value.is_number() &&
            value.get<double>() == quantity.metres;
    } catch (const std::exception&) {
        return false;
    }
}

std::optional<json> merged_quantity_entries(const Entity* original, const Entity& proposed,
                                           const json& canonical_properties) {
    const auto new_entries = proposed.properties.find("quantity_entries");
    const json* old_entries = original && original->properties.contains("quantity_entries")
        ? &original->properties.at("quantity_entries") : nullptr;
    const json* entries = new_entries != proposed.properties.end() ? &*new_entries : old_entries;
    if (!entries) return std::nullopt;
    if (!entries->is_object()) throw std::invalid_argument("Quantity entries must be an object.");
    json result = json::object();
    for (const auto& [pointer, receipt] : entries->items()) {
        auto original_pointer = pointer;
        bool has_original_binding = true;
        const auto child_key = pointer.starts_with("/flights/") ? "flights" : "landings";
        const auto child_prefix = std::string("/") + child_key + "/";
        if (original && pointer.starts_with(child_prefix) && is_building_quantity_path(pointer) &&
            canonical_properties.contains(child_key) && original->properties.contains(child_key)) {
            const auto separator = pointer.find('/', child_prefix.size());
            const auto row = static_cast<std::size_t>(std::stoul(pointer.substr(child_prefix.size(), separator - child_prefix.size())));
            const auto& next = canonical_properties.at(child_key);
            const auto& before = original->properties.at(child_key);
            has_original_binding = false;
            if (next.is_array() && row < next.size() && before.is_array()) {
                const auto id = next.at(row).at("id");
                for (std::size_t old_row = 0; old_row < before.size(); ++old_row)
                    if (before.at(old_row).is_object() && before.at(old_row).value("id", json{}) == id) {
                        original_pointer = child_prefix + std::to_string(old_row) + pointer.substr(separator);
                        has_original_binding = true;
                        break;
                    }
            }
        }
        if (original && original->type=="stair" && pointer.starts_with(child_prefix) &&
            is_building_quantity_path(pointer) && !original->properties.contains(child_key)) has_original_binding = false;
        const json* prior = has_original_binding && old_entries && old_entries->is_object() &&
            old_entries->contains(original_pointer) ? &old_entries->at(original_pointer) : nullptr;
        if (quantity_entry_matches(receipt, canonical_properties, pointer)) {
            if (original && (original->type=="column" || original->type=="beam" ||
                    original->type=="stair" || original->type=="railing") && prior && prior->is_object() && receipt.is_object() &&
                prior->value("version",json{})==1 && receipt.value("version",json{})==1) {
                auto retained=*prior;
                for (const auto* key:{"version","original_expression","entered_unit"}) retained[key]=receipt.at(key);
                for (const auto* key:{"numerator","denominator"})
                    retained["exact_metres"][key]=receipt.at("exact_metres").at(key);
                result[pointer]=std::move(retained);
            } else result[pointer] = receipt;
            continue;
        }
        const bool inherited = has_original_binding && old_entries && old_entries->is_object() && old_entries->contains(original_pointer) &&
            old_entries->at(original_pointer) == receipt;
        if (!inherited)
            throw std::invalid_argument("Quantity entry does not match its canonical dimension: " + pointer);
        if (!is_building_quantity_path(pointer)) {
            result[pointer] = receipt;
            continue;
        }
        // Unknown legacy records survive untouched geometry. A programmatic
        // dimension change invalidates its old receipt instead of retaining a
        // measurement expression that now describes a different value.
        try {
            const json::json_pointer before_path(original_pointer), after_path(pointer);
            const bool before = original->properties.contains(before_path);
            const bool after = canonical_properties.contains(after_path);
            if ((!before && !after) ||
                (before && after && original->properties.at(before_path) == canonical_properties.at(after_path)))
                result[pointer] = receipt;
        } catch (const std::exception&) {
            // An unrecognized pointer is metadata, not an authoritative entry.
            result[pointer] = receipt;
        }
    }
    if (original && (original->type=="column" || original->type=="beam") && old_entries && old_entries->is_object())
        for (const auto& [pointer,receipt]:old_entries->items()) if (!result.contains(pointer)) {
            if (!is_building_quantity_path(pointer)) { result[pointer]=receipt; continue; }
            try {
                const json::json_pointer path(pointer);
                if (original->properties.contains(path) && canonical_properties.contains(path) &&
                    original->properties.at(path)==canonical_properties.at(path)) result[pointer]=receipt;
            } catch (const json::exception&) { result[pointer]=receipt; }
        }
    return result;
}

// Canonical geometry replaces only understood fields. Retain opaque members of
// nested objects and stable-ID records instead of losing them through update().
json merge_canonical_metadata(const json& retained, const json& edited, const json& canonical) {
    if (canonical.is_object()) {
        auto result = retained.is_object() ? retained : json::object();
        if (edited.is_object()) result.update(edited);
        for (const auto& [key, value] : canonical.items()) {
            result[key] = merge_canonical_metadata(
                retained.is_object() && retained.contains(key) ? retained.at(key) : json{},
                edited.is_object() && edited.contains(key) ? edited.at(key) : json{}, value);
        }
        return result;
    }
    if (canonical.is_array() && !canonical.empty() && canonical.front().is_object() &&
        canonical.front().contains("id")) {
        auto result = json::array();
        const auto record = [](const json& array, const json& id) -> json {
            if (array.is_array()) for (const auto& item : array)
                if (item.is_object() && item.contains("id") && item.at("id") == id) return item;
            return {};
        };
        for (const auto& item : canonical) {
            if (!item.is_object() || !item.contains("id")) return canonical;
            result.push_back(merge_canonical_metadata(record(retained, item.at("id")),
                record(edited, item.at("id")), item));
        }
        return result;
    }
    return canonical;
}

json retain_unchanged_structural_numbers(const json& original, const json& candidate) {
    if (original.is_number() && candidate.is_number() && original==candidate) return original;
    auto result=candidate;
    if (original.is_array() && candidate.is_array() && original.size()==candidate.size())
        for (std::size_t index=0;index<candidate.size();++index)
            result[index]=retain_unchanged_structural_numbers(original.at(index),candidate.at(index));
    else if (original.is_object() && candidate.is_object())
        for (const auto& [key,value]:candidate.items()) if (original.contains(key))
            result[key]=retain_unchanged_structural_numbers(original.at(key),value);
    return result;
}

Entity effective_building_geometry_entity(const DocumentSnapshot& snapshot, const Entity& entity) {
    return hosted_stair_railing(entity) ? entity : resolve_vertical_placement(snapshot, entity);
}

std::string building_plan_source_key(const DocumentSnapshot& snapshot, const Entity& effective) {
    std::string key = effective.type + '\n' + effective.properties.dump();
    if (hosted_stair_railing(effective)) {
        const auto rail = decode_railing_properties(effective.id, effective.properties);
        const auto host = snapshot.entities().find(stair_railing_host_id(rail));
        if (host == snapshot.entities().end()) throw std::invalid_argument("Stair railing host is missing.");
        key += '\n' + host->second.properties.dump() + '\n' +
            resolve_vertical_placement(snapshot, host->second).properties.dump();
    }
    return key;
}

void retain_plan_endpoint_handles(CanvasEntity& entity,
    const std::array<std::pair<Vec3, QString>, 2>& endpoints, Revision revision,
    bool interactive, const ArchitecturalViewContext* view = nullptr) {
    entity.vertex_handles.clear();
    entity.endpoint_baseline.reset();
    if (!interactive || !entity.selected || (view && !horizontal_plan_frame(view->frame))) return;
    for (const auto& [endpoint, role] : endpoints) {
        if (view && std::isfinite(view->depth.far_depth_m)) {
            const auto& depth = view->depth;
            const Vec3 plane_origin{
                depth.origin.x + depth.direction.x * depth.far_depth_m,
                depth.origin.y + depth.direction.y * depth.far_depth_m,
                depth.origin.z + depth.direction.z * depth.far_depth_m};
            const auto distance = (endpoint.x - plane_origin.x) * depth.direction.x +
                (endpoint.y - plane_origin.y) * depth.direction.y +
                (endpoint.z - plane_origin.z) * depth.direction.z;
            // A partially clipped solid remains visible, but its hidden axis
            // endpoint must not become an authoring grip at the cut plane.
            if (!std::isfinite(distance) || distance > 0.0) continue;
        }
        const Vec2 model{endpoint.x, endpoint.y};
        const auto point = view ? project_plan_point(model, view->frame) : model;
        if (view && view->crop) {
            const auto& crop = *view->crop;
            if (point.x < crop.min_horizontal_m || point.x > crop.max_horizontal_m ||
                point.y < crop.min_vertical_m || point.y > crop.max_vertical_m) continue;
        }
        entity.vertex_handles.push_back({role, point, revision});
    }
}

void retain_building_endpoint_handles(CanvasEntity& entity, const BuildingObject& object,
    Revision revision, bool interactive, const ArchitecturalViewContext* view = nullptr) {
    if (const auto* beam = std::get_if<Beam>(&object)) {
        retain_plan_endpoint_handles(entity, {{{beam->start, QStringLiteral("beam:start")},
            {beam->end, QStringLiteral("beam:end")}}}, revision, interactive, view);
    } else if (const auto* rail = std::get_if<Railing>(&object)) {
        entity.vertex_handles.clear();
        entity.endpoint_baseline.reset();
        // Hosted railings inherit their endpoints from the stair or landing;
        // displaying independent grips would offer an edit the host owns.
        if (rail->host || rail->landing_host) return;
        const Vec3 end{rail->base_position.x + rail->length * std::cos(rail->orientation_radians),
            rail->base_position.y + rail->length * std::sin(rail->orientation_radians), rail->base_position.z};
        retain_plan_endpoint_handles(entity, {{{rail->base_position, QStringLiteral("railing:start")},
            {end, QStringLiteral("railing:end")}}}, revision, interactive, view);
    }
}

DocumentRoomFootprint architectural_footprint(const Entity& source) {
    if (source.type == "slab") {
        const auto boundary = read_required_boundary(source.properties, "boundary");
        const auto holes = read_required_holes(source.properties);
        if (!boundary || !holes) throw std::invalid_argument("The slab footprint is unavailable.");
        return {*boundary, *holes};
    }
    DocumentRoomFootprint footprint;
    std::string error;
    if (source.type != "room" || !read_document_room_footprint(source, footprint, error))
        throw std::invalid_argument("The room footprint is unavailable: " + error);
    return footprint;
}

void retain_footprint_vertex_handles(CanvasEntity& entity, const Entity& source, Revision revision,
    bool interactive, const ArchitecturalViewContext* view = nullptr) {
    entity.vertex_handles.clear();
    entity.endpoint_baseline.reset();
    if (!interactive || !entity.selected || (view && !horizontal_plan_frame(view->frame)) ||
        source.extensions.contains("physical_wall_room") ||
        source.properties.contains("wall_measurement_source")) return;
    const auto footprint = architectural_footprint(source);
    const auto retained_point = [&](Vec2 point) {
        if (view && view->crop) {
            const auto& crop = *view->crop;
            if (point.x < crop.min_horizontal_m || point.x > crop.max_horizontal_m ||
                point.y < crop.min_vertical_m || point.y > crop.max_vertical_m) return false;
        }
        // Authoring grips belong to actual retained source vertices, never to
        // new crop/depth intersections. Query the projected analytical paths
        // so a hidden or completely clipped ring offers no invisible grip.
        constexpr auto tolerance = default_geometry_tolerance_metres;
        const Bounds2 vicinity{{point.x - tolerance, point.y - tolerance},
                               {point.x + tolerance, point.y + tolerance}};
        const auto intersects = [&](const Boundary& path) {
            return !clip_boundary_to_bounds(path, vicinity, tolerance / 16.0).empty();
        };
        try {
            if (intersects(entity.segments)) return true;
            if (entity.stroke_segments && intersects(*entity.stroke_segments)) return true;
            return std::any_of(entity.holes.begin(), entity.holes.end(), intersects);
        } catch (const std::exception&) { return false; }
    };
    const auto retain_ring = [&](const Boundary& ring, const QString& prefix) {
        for (std::size_t index = 0; index < ring.size(); ++index) {
            const auto point = view ? project_plan_point(ring[index].start, view->frame) : ring[index].start;
            if (retained_point(point))
                entity.vertex_handles.push_back({prefix + QString::number(static_cast<qulonglong>(index)), point, revision});
        }
    };
    retain_ring(footprint.boundary, QStringLiteral("footprint:outer:"));
    for (std::size_t hole = 0; hole < footprint.holes.size(); ++hole)
        retain_ring(footprint.holes[hole], QStringLiteral("footprint:hole:%1:").arg(static_cast<qulonglong>(hole)));
}

void retain_roof_plan_corner_handles(CanvasEntity& entity, Revision revision, bool interactive) {
    entity.vertex_handles.clear();
    entity.endpoint_baseline.reset();
    if (!interactive || !entity.selected || !entity.resize_frame || entity.segments.empty()) return;
    const auto& frame=*entity.resize_frame;
    if (!std::isfinite(frame.center.x) || !std::isfinite(frame.center.y) ||
        !std::isfinite(frame.rotation_radians) || !std::isfinite(frame.width_metres) ||
        !std::isfinite(frame.depth_metres) || frame.width_metres<=0 || frame.depth_metres<=0 ||
        (frame.source_rotation_direction!=1.0 && frame.source_rotation_direction!=-1.0)) return;
    const auto c=std::cos(frame.rotation_radians),s=std::sin(frame.rotation_radians);
    const std::array<Vec2,4> corners{{{-frame.width_metres*.5,-frame.depth_metres*.5},
        {frame.width_metres*.5,-frame.depth_metres*.5},
        {frame.width_metres*.5,frame.depth_metres*.5},
        {-frame.width_metres*.5,frame.depth_metres*.5}}};
    for (std::size_t index=0;index<corners.size();++index) {
        const auto x=corners[index].x,y=corners[index].y*frame.source_rotation_direction;
        const Vec2 point{frame.center.x+c*x-s*y,frame.center.y+s*x+c*y};
        constexpr auto tolerance=default_geometry_tolerance_metres;
        const Bounds2 vicinity{{point.x-tolerance,point.y-tolerance},{point.x+tolerance,point.y+tolerance}};
        // Only genuine full-footprint corners that survive the actual crop,
        // depth and joined geometry offer grips. Crop intersections never do.
        bool visible{};
        try {
            visible=!clip_boundary_to_bounds(entity.segments,vicinity,tolerance/16.0).empty() ||
                (entity.stroke_segments && !clip_boundary_to_bounds(*entity.stroke_segments,vicinity,tolerance/16.0).empty());
        } catch (const std::exception&) { continue; }
        if (visible) entity.vertex_handles.push_back({QStringLiteral("roof:corner:%1").arg(
            static_cast<qulonglong>(index)),point,revision});
    }
}

TopoDS_Shape document_roof_join_shape(const DocumentSnapshot& snapshot, const Entity& entity) {
    const auto join = parse_roof_join(entity.properties, entity.id);
    std::vector<TopoDS_Shape> roofs;
    roofs.reserve(join.roof_ids.size());
    for (const auto& id : join.roof_ids) {
        const auto& roof = snapshot.entities().at(id);
        if (roof.type != "roof") throw std::invalid_argument("Joined roof member has the wrong type.");
        roofs.push_back(make_building_shape(decode_building_entity(
            effective_building_geometry_entity(snapshot, roof)), snapshot.entities()));
    }
    return make_roof_join(join, roofs);
}

