    struct ShortcutBinding {
        QString id;
        QAction* action{};
        QKeySequence standard;
        QKeySequence apex;
    };

    QString shortcutSettingsPath() const {
        return QStandardPaths::writableLocation(QStandardPaths::AppConfigLocation) +
               QStringLiteral("/keyboard-shortcuts.json");
    }

    QString validateShortcuts(const std::vector<QKeySequence>& keys) const {
        // Canvas editing and text controls retain their ordinary editing keys.
        const std::vector<QKeySequence> reserved{
            QKeySequence::Undo, QKeySequence::Redo, QKeySequence::Copy,
            QKeySequence::Cut, QKeySequence::Paste, QKeySequence::SelectAll,
            QKeySequence(QStringLiteral("Ctrl+Shift+Z")),
            QKeySequence(QStringLiteral("Shift+F10"))};
        for (std::size_t index = 0; index < keys.size(); ++index) {
            const auto& sequence = keys[index];
            if (sequence.isEmpty()) continue;
            if (sequence.count() != 1) return QStringLiteral("Use one key combination per command.");
            const auto key = sequence[0].key();
            const auto modifiers = sequence[0].keyboardModifiers();
            if (key == Qt::Key_unknown || key == Qt::Key_Control || key == Qt::Key_Shift ||
                key == Qt::Key_Alt || key == Qt::Key_Meta || key == Qt::Key_Menu ||
                key == Qt::Key_Tab || key == Qt::Key_Backtab ||
                key == Qt::Key_Return || key == Qt::Key_Enter || key == Qt::Key_Escape ||
                key == Qt::Key_Backspace || key == Qt::Key_Delete || key == Qt::Key_Insert ||
                (key >= Qt::Key_Home && key <= Qt::Key_PageDown) ||
                (!(modifiers & (Qt::ControlModifier | Qt::AltModifier | Qt::MetaModifier)) &&
                 !(key >= Qt::Key_F1 && key <= Qt::Key_F35)) ||
                std::find(reserved.begin(), reserved.end(), sequence) != reserved.end()) {
                return QStringLiteral("%1 is reserved for text entry or canvas editing.")
                    .arg(sequence.toString(QKeySequence::NativeText));
            }
            for (std::size_t other = 0; other < index; ++other) {
                if (keys[other] == sequence) {
                    return QStringLiteral("%1 is assigned more than once.")
                        .arg(sequence.toString(QKeySequence::NativeText));
                }
            }
        }
        return {};
    }

    void initializeShortcuts() {
        const auto add = [this](QString id, QAction* action, const char* standard, const char* apex) {
            m_shortcuts.push_back({std::move(id), action, QKeySequence(QString::fromLatin1(standard)),
                                  QKeySequence(QString::fromLatin1(apex))});
        };
        add(QStringLiteral("new"), m_new_action, "Ctrl+N", "Ctrl+N");
        add(QStringLiteral("open"), m_open_action, "Ctrl+O", "F3");
        add(QStringLiteral("save"), m_save_action, "Ctrl+S", "F2");
        add(QStringLiteral("save-as"), m_save_as_action, "Ctrl+Shift+S", "Ctrl+Shift+S");
        add(QStringLiteral("commands"), m_palette_action, "Ctrl+K", "Ctrl+K");
        add(QStringLiteral("measurement"), m_measurement_action, "Ctrl+1", "Ctrl+1");
        add(QStringLiteral("architectural"), m_architectural_action, "Ctrl+2", "Ctrl+2");
        add(QStringLiteral("annotations"), m_annotation_action, "Ctrl+Shift+A", "Ctrl+Shift+A");
        auto* define = new QAction(QStringLiteral("Define area before drawing"), owner);
        define->setObjectName(QStringLiteral("defineAreaShortcut"));
        owner->addAction(define);
        QObject::connect(define, &QAction::triggered, owner, [this] {
            (void)beginBoundaryDrawing(BoundaryAuthoringMode::define_first, {});
        });
        m_auto_subtract_action=new QAction(QStringLiteral("Subtract from area…"),owner);
        m_auto_subtract_action->setObjectName(QStringLiteral("autoSubtract"));
        owner->addAction(m_auto_subtract_action);
        QObject::connect(m_auto_subtract_action,&QAction::triggered,owner,[this] { showAutoSubtractDialog(); });
        m_draw_subtract_action=new QAction(QStringLiteral("Define area and subtract from…"),owner);
        m_draw_subtract_action->setObjectName(QStringLiteral("drawSubtractingArea"));
        owner->addAction(m_draw_subtract_action);
        QObject::connect(m_draw_subtract_action,&QAction::triggered,owner,[this] { showAutoSubtractDialog(true); });
        add(QStringLiteral("define-area"), define, "Ctrl+Shift+D", "F4");
        for (const auto& binding : m_shortcuts) binding.action->setShortcut(binding.standard);

        QFile file(shortcutSettingsPath());
        if (!file.exists()) return;
        try {
            if (!file.open(QIODevice::ReadOnly) || file.size() > 64 * 1024)
                throw std::runtime_error("Shortcut settings cannot be read.");
            const auto settings_document = json::parse(file.readAll().toStdString());
            if (!settings_document.is_object() || settings_document.size() != 2 ||
                !settings_document.at("version").is_number_integer() || settings_document.at("version") != 1 ||
                !settings_document.at("bindings").is_object() || settings_document.at("bindings").size() != m_shortcuts.size())
                throw std::runtime_error("Unsupported shortcut settings.");
            std::vector<QKeySequence> keys;
            for (const auto& binding : m_shortcuts) {
                const auto text = QString::fromStdString(
                    settings_document.at("bindings").at(binding.id.toStdString()).get<std::string>());
                const auto sequence = QKeySequence::fromString(text, QKeySequence::PortableText);
                if (sequence.toString(QKeySequence::PortableText) != text)
                    throw std::runtime_error("Invalid shortcut text.");
                keys.push_back(sequence);
            }
            if (!validateShortcuts(keys).isEmpty()) throw std::runtime_error("Conflicting or reserved shortcuts.");
            for (std::size_t index = 0; index < keys.size(); ++index)
                m_shortcuts[index].action->setShortcut(keys[index]);
        } catch (const std::exception&) {
            m_shortcut_load_error = QStringLiteral("Saved shortcuts could not be loaded. Default bindings are active.");
        }
    }

    void showShortcutSettings() {
        QDialog dialog(owner);
        styleDialog(dialog);
        dialog.setObjectName(QStringLiteral("keyboardShortcutDialog"));
        dialog.setWindowTitle(QStringLiteral("Keyboard shortcuts"));
        auto* layout = new QVBoxLayout(&dialog);
        auto* presets = new QComboBox(&dialog);
        presets->setObjectName(QStringLiteral("keyboardShortcutPreset"));
        presets->addItems({QStringLiteral("Current bindings"), QStringLiteral("Vertex defaults"),
                           QStringLiteral("Apex v7 compatible subset")});
        layout->addWidget(presets);
        auto* help = new QLabel(QStringLiteral(
            "Apex subset: F2 Save, F3 Open, F4 Define area. Other commands retain Studio defaults. "
            "Text editing and canvas keys remain reserved. Clear a binding to disable it."), &dialog);
        help->setWordWrap(true);
        layout->addWidget(help);
        auto* form = new QFormLayout;
        std::vector<QKeySequenceEdit*> editors;
        for (const auto& binding : m_shortcuts) {
            auto* edit = new QKeySequenceEdit(binding.action->shortcut(), &dialog);
            edit->setMaximumSequenceLength(1);
            edit->setClearButtonEnabled(true);
            edit->setObjectName(QStringLiteral("shortcut-") + binding.id);
            edit->setAccessibleName(binding.action->text());
            form->addRow(binding.action->text(), edit);
            editors.push_back(edit);
        }
        layout->addLayout(form);
        auto* status = new QLabel(m_shortcut_load_error, &dialog);
        status->setObjectName(QStringLiteral("keyboardShortcutStatus"));
        status->setWordWrap(true);
        layout->addWidget(status);
        auto* buttons = new QDialogButtonBox(QDialogButtonBox::Save | QDialogButtonBox::Cancel, &dialog);
        buttons->setObjectName(QStringLiteral("keyboardShortcutButtons"));
        layout->addWidget(buttons);
        QObject::connect(presets, &QComboBox::currentIndexChanged, &dialog, [&](int preset) {
            for (std::size_t index = 0; index < editors.size(); ++index) {
                const auto& binding = m_shortcuts[index];
                editors[index]->setKeySequence(preset == 1 ? binding.standard :
                                               preset == 2 ? binding.apex : binding.action->shortcut());
            }
        });
        QObject::connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
        QObject::connect(buttons, &QDialogButtonBox::accepted, &dialog, [&] {
            std::vector<QKeySequence> keys;
            for (auto* editor : editors) keys.push_back(editor->keySequence());
            const auto error = validateShortcuts(keys);
            if (!error.isEmpty()) { status->setText(error); return; }
            json settings_document{{"version", 1}, {"bindings", json::object()}};
            for (std::size_t index = 0; index < keys.size(); ++index)
                settings_document["bindings"][m_shortcuts[index].id.toStdString()] =
                    keys[index].toString(QKeySequence::PortableText).toStdString();
            const auto bytes = QByteArray::fromStdString(settings_document.dump(2));
            QSaveFile file(shortcutSettingsPath());
            if (!QDir().mkpath(QFileInfo(file.fileName()).absolutePath()) ||
                !file.open(QIODevice::WriteOnly) || file.write(bytes) != bytes.size() || !file.commit()) {
                status->setText(QStringLiteral("Could not save shortcuts. Existing bindings remain active."));
                return;
            }
            for (std::size_t index = 0; index < keys.size(); ++index)
                m_shortcuts[index].action->setShortcut(keys[index]);
            m_shortcut_load_error.clear();
            dialog.accept();
        });
        dialog.exec();
    }

    void showMeasurementKeypad() {
        QDialog dialog(owner);
        styleDialog(dialog);
        dialog.setObjectName(QStringLiteral("measurementKeypadDialog"));
        dialog.setWindowTitle(QStringLiteral("Measurement keypad"));
        auto* layout = new QVBoxLayout(&dialog);
        auto* target = new QComboBox(&dialog);
        target->setObjectName(QStringLiteral("measurementKeypadTarget"));
        target->setAccessibleName(QStringLiteral("Dimension to edit"));
        const std::array<QLineEdit*, 3> fields{m_length_edit, m_height_edit, m_thickness_edit};
        const std::array<QString, 3> names{QStringLiteral("Length"), QStringLiteral("Height"), QStringLiteral("Thickness")};
        const auto selected = selectedEntity();
        const bool wall = selected && selected->type == "wall";
        const bool opening = selected && selected->type == "opening";
        const bool slab = selected && selected->type == "slab";
        const bool room = selected && selected->type == "room";
        const bool closed_boundary = selected && is_closed_boundary_entity(selected->type);
        const std::array<bool, 3> relevant{
            wall || opening || slab || closed_boundary,
            wall || opening || room,
            wall || slab,
        };
        for (std::size_t index = 0; index < fields.size(); ++index) {
            // The properties panel is opt-in and may remain closed. Field
            // relevance comes from the selected model object, not whether the
            // panel has ever been painted.
            if (relevant[index] && !fields[index]->isReadOnly())
                target->addItem(names[index], static_cast<int>(index));
        }
        layout->addWidget(target);
        auto* input = new QLineEdit(&dialog);
        input->setObjectName(QStringLiteral("measurementKeypadValue"));
        input->setAccessibleName(QStringLiteral("Measurement expression"));
        layout->addWidget(input);
        auto* hint = new QLabel(m_metric_units ? QStringLiteral("Default unit: metres. Fractions and explicit units are accepted.") :
                                              QStringLiteral("Default unit: feet. Fractions and explicit units are accepted."), &dialog);
        hint->setWordWrap(true);
        layout->addWidget(hint);
        auto* grid = new QGridLayout;
        const QStringList tokens{QStringLiteral("7"), QStringLiteral("8"), QStringLiteral("9"), QStringLiteral("/"),
                                 QStringLiteral("4"), QStringLiteral("5"), QStringLiteral("6"), QStringLiteral("."),
                                 QStringLiteral("1"), QStringLiteral("2"), QStringLiteral("3"), QStringLiteral(" "),
                                 QStringLiteral("0"), QStringLiteral("ft"), QStringLiteral("in"), QStringLiteral("m"),
                                 QStringLiteral("mm"), QStringLiteral("cm")};
        for (int index = 0; index < tokens.size(); ++index) {
            const auto token = tokens[index];
            auto* button = new QPushButton(token == QStringLiteral(" ") ? QStringLiteral("Space") : token, &dialog);
            button->setObjectName(QStringLiteral("measurementKeypadToken%1").arg(index));
            button->setMinimumSize(48, 40);
            button->setAutoDefault(false);
            grid->addWidget(button, index / 4, index % 4);
            QObject::connect(button, &QPushButton::clicked, &dialog, [input, token] {
                input->insert(token); input->setFocus();
            });
        }
        auto* erase = new QPushButton(QStringLiteral("Backspace"), &dialog);
        erase->setAutoDefault(false);
        grid->addWidget(erase, 4, 2, 1, 2);
        QObject::connect(erase, &QPushButton::clicked, input, [input] { input->backspace(); input->setFocus(); });
        layout->addLayout(grid);
        auto* status = new QLabel(&dialog);
        status->setObjectName(QStringLiteral("measurementKeypadStatus"));
        status->setWordWrap(true);
        layout->addWidget(status);
        auto* buttons = new QDialogButtonBox(QDialogButtonBox::Apply | QDialogButtonBox::Cancel, &dialog);
        buttons->setObjectName(QStringLiteral("measurementKeypadButtons"));
        layout->addWidget(buttons);
        const auto selected_id = m_selected_id;
        const auto revision = m_document->revision();
        const auto document_id = m_document->snapshot().document_id();
        const auto load = [&] {
            if (target->count()) input->setText(fields[static_cast<std::size_t>(target->currentData().toInt())]->text());
            input->selectAll();
            input->setFocus();
        };
        QObject::connect(target, &QComboBox::currentIndexChanged, &dialog, load);
        load();
        buttons->button(QDialogButtonBox::Apply)->setEnabled(target->count() > 0);
        if (!target->count()) status->setText(QStringLiteral("Select an editable dimensioned object first."));
        QObject::connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
        bool wall_length = false;
        QObject::connect(buttons->button(QDialogButtonBox::Apply), &QPushButton::clicked, &dialog, [&] {
            if (m_selected_id != selected_id || m_document->revision() != revision ||
                m_document->snapshot().document_id() != document_id) {
                status->setText(QStringLiteral("The selection or document changed. Reopen the keypad.")); return;
            }
            const auto index = target->currentData().toInt();
            const auto entity = selectedEntity();
            wall_length = index == 0 && entity && entity->type == "wall";
            if (wall_length) {
                try {
                    if (!(parse_quantity(input->text().toStdString(), m_metric_units ? Unit::metre : Unit::foot).metres > 0.0))
                        throw std::invalid_argument("Length must be positive.");
                } catch (const std::exception& error) { status->setText(QString::fromUtf8(error.what())); return; }
                dialog.accept(); // Continue through the existing constraint preview.
            } else {
                const bool ok = index == 0 ? editSelectedLength(input->text()) :
                                index == 1 ? editSelectedHeight(input->text()) : editSelectedThickness(input->text());
                if (ok) dialog.accept(); else status->setText(lastError());
            }
        });
        if (dialog.exec() == QDialog::Accepted && wall_length) showConstraintEditor(input->text());
    }

    void showDistoImport() {
        const auto source = authoringSnapshot();
        const auto authority = captureSourceEditAuthority(source);
        const auto selected = source.entities().find(m_selected_id.toStdString());
        QDialog dialog(owner);
        styleDialog(dialog);
        dialog.setObjectName(QStringLiteral("distoImportDialog"));
        dialog.setWindowTitle(QStringLiteral("Measurement input"));
        dialog.setModal(true);
        dialog.resize(600, 420);
        auto* layout = new QVBoxLayout(&dialog);
        auto* selection = new QLabel(&dialog);
        selection->setObjectName(QStringLiteral("distoSelection"));
        selection->setTextFormat(Qt::PlainText);
        selection->setText(selected == source.entities().end() || m_selected_ids.size() != 1
            ? QStringLiteral("Select one wall, opening, slab or room before entering a measurement.")
            : QStringLiteral("%1").arg(QString::fromStdString(
                selected->second.properties.value("name", selected->first))));
        selection->setWordWrap(true);
        layout->addWidget(selection);
        auto* tabs = new QTabWidget(&dialog);
        tabs->setObjectName(QStringLiteral("distoInputTabs"));
        auto* keyboard = new QWidget(tabs);
        auto* keyboard_layout = new QVBoxLayout(keyboard);
        auto* guidance = new QLabel(QStringLiteral(
            "Pair a keyboard-capable measuring device in Windows, select the unit used on the device, "
            "then send its reading to the Measurement field."), keyboard);
        guidance->setWordWrap(true);
        keyboard_layout->addWidget(guidance);
        auto* form = new QFormLayout;
        auto* device = new QLineEdit(keyboard);
        device->setObjectName(QStringLiteral("distoDeviceName"));
        device->setMaxLength(128);
        device->setPlaceholderText(QStringLiteral("Device name or model"));
        form->addRow(QStringLiteral("Device"), device);
        auto* target = new QComboBox(keyboard);
        target->setObjectName(QStringLiteral("distoTargetField"));
        if (selected != source.entities().end() && m_selected_ids.size() == 1) {
            const auto& type = selected->second.type;
            if (type == "wall") {
                target->addItem(QStringLiteral("Length"), QStringLiteral("wall.length"));
                target->addItem(QStringLiteral("Height"), QStringLiteral("wall.height"));
                target->addItem(QStringLiteral("Thickness"), QStringLiteral("wall.thickness"));
                target->addItem(QStringLiteral("Base elevation"), QStringLiteral("wall.elevation"));
            } else if (type == "opening") {
                target->addItem(QStringLiteral("Width"), QStringLiteral("opening.width"));
                target->addItem(QStringLiteral("Height"), QStringLiteral("opening.height"));
            } else if (type == "slab") {
                target->addItem(QStringLiteral("Thickness"), QStringLiteral("slab.thickness"));
                target->addItem(QStringLiteral("Base elevation"), QStringLiteral("slab.elevation"));
            } else if (type == "room") {
                target->addItem(QStringLiteral("Height"), QStringLiteral("room.height"));
                target->addItem(QStringLiteral("Base elevation"), QStringLiteral("room.elevation"));
            }
        }
        form->addRow(QStringLiteral("Field"), target);
        auto* current_reading = new QLabel(keyboard);
        current_reading->setObjectName(QStringLiteral("distoCurrentMeasurement"));
        current_reading->setTextFormat(Qt::PlainText);
        current_reading->setWordWrap(true);
        form->addRow(current_reading);
        const auto update_current_reading = [&] {
            current_reading->clear();
            if (selected == source.entities().end() || target->count() == 0) return;
            const auto field = target->currentData().toString().toStdString();
            std::optional<double> current;
            if (field == "wall.length") {
                if (const auto baseline = read_required_segment(selected->second.properties, "baseline")) {
                    try { current = segment_length(*baseline); }
                    catch (const std::exception&) { /* The Apply path reports invalid geometry. */ }
                }
            } else {
                const auto key = field == "opening.width" ? "width_m"
                    : field.ends_with(".height") ? "height_m"
                    : field.ends_with(".thickness") ? "thickness_m" : "elevation_m";
                current = read_finite_number(selected->second.properties, key);
            }
            auto description = current
                ? QStringLiteral("Current %1: %2").arg(target->currentText().toLower(),
                    format_length(*current, m_metric_units))
                : QStringLiteral("Current dimension is unavailable.");
            const auto prior = selected->second.extensions.find("disto_measurements");
            if (prior != selected->second.extensions.end()) {
                try {
                    if (prior->at("fields").contains(field)) {
                        const auto record = parse_disto_measurement_json(prior->at("fields").at(field).dump());
                        description += QStringLiteral("\nRecorded: %1 %2 · %3 · %4").arg(
                            QString::number(record.value, 'g', 12), QString::fromStdString(record.unit),
                            QString::fromStdString(record.model), QString::fromStdString(record.captured_at));
                    }
                } catch (const std::exception&) {
                    description += QStringLiteral("\nThe saved reading is malformed; it cannot be replaced here.");
                }
            }
            current_reading->setText(description);
        };
        QObject::connect(target, &QComboBox::currentIndexChanged, &dialog,
            [&](int) { update_current_reading(); });
        update_current_reading();
        auto* units = new QComboBox(keyboard);
        units->setObjectName(QStringLiteral("distoSourceUnit"));
        units->setPlaceholderText(QStringLiteral("Select the device unit"));
        for (const auto& [label, value] : std::array<std::pair<const char*, const char*>, 5>{
                {{"Metres", "m"}, {"Centimetres", "cm"}, {"Millimetres", "mm"},
                 {"Feet (decimal)", "ft"}, {"Inches (decimal)", "in"}}})
            units->addItem(QString::fromLatin1(label), QString::fromLatin1(value));
        units->setCurrentIndex(-1);
        form->addRow(QStringLiteral("Device unit"), units);
        auto* decimal = new QComboBox(keyboard);
        decimal->setObjectName(QStringLiteral("distoDecimalSeparator"));
        decimal->addItem(QStringLiteral("Dot (12.34)"), QStringLiteral("."));
        decimal->addItem(QStringLiteral("Comma (12,34)"), QStringLiteral(","));
        form->addRow(QStringLiteral("Decimal"), decimal);
        auto* reading = new QLineEdit(keyboard);
        reading->setObjectName(QStringLiteral("distoKeyboardReading"));
        reading->setMaxLength(256);
        reading->setAccessibleName(QStringLiteral("Measurement from device"));
        reading->setPlaceholderText(QStringLiteral("Send or enter one measurement"));
        form->addRow(QStringLiteral("Measurement"), reading);
        keyboard_layout->addLayout(form);
        keyboard_layout->addStretch(1);
        tabs->addTab(keyboard, QStringLiteral("Keyboard"));
        auto* adapter = new QWidget(tabs);
        auto* adapter_layout = new QVBoxLayout(adapter);
        auto* description = new QLabel(QStringLiteral(
            "Load a reading from a device adapter, or paste its measurement record."), adapter);
        description->setWordWrap(true);
        adapter_layout->addWidget(description);
        auto* payload = new QPlainTextEdit(adapter);
        payload->setObjectName(QStringLiteral("distoPayload"));
        payload->setAccessibleName(QStringLiteral("DISTO measurement JSON"));
        payload->setPlaceholderText(QStringLiteral(
            "{\"protocol_version\":{\"major\":1,\"minor\":0},...}"));
        payload->setTabChangesFocus(true);
        adapter_layout->addWidget(payload, 1);
        auto* file_row = new QHBoxLayout;
        auto* load = new QPushButton(QStringLiteral("Load reading file…"), adapter);
        load->setObjectName(QStringLiteral("loadDistoJson"));
        file_row->addWidget(load);
        file_row->addStretch(1);
        adapter_layout->addLayout(file_row);
        tabs->addTab(adapter, QStringLiteral("Adapter file"));
        layout->addWidget(tabs, 1);
        auto* replace = new QCheckBox(QStringLiteral("Replace existing measurement"), &dialog);
        replace->setObjectName(QStringLiteral("distoReplaceExisting"));
        replace->setVisible(selected != source.entities().end() &&
            selected->second.extensions.contains("disto_measurements"));
        layout->addWidget(replace);
        auto* status = new QLabel(&dialog);
        status->setObjectName(QStringLiteral("distoImportStatus"));
        status->setTextFormat(Qt::PlainText);
        status->setWordWrap(true);
        layout->addWidget(status);
        auto* buttons = new QDialogButtonBox(QDialogButtonBox::Apply | QDialogButtonBox::Cancel,
                                             &dialog);
        buttons->button(QDialogButtonBox::Apply)->setText(QStringLiteral("Apply reading"));
        buttons->button(QDialogButtonBox::Apply)->setObjectName(QStringLiteral("applyDistoReading"));
        layout->addWidget(buttons);
        const auto update_apply = [&] {
            const bool owner_ready = selected != source.entities().end() && m_selected_ids.size() == 1;
            buttons->button(QDialogButtonBox::Apply)->setEnabled(owner_ready &&
                (tabs->currentIndex() == 1 ? !payload->toPlainText().trimmed().isEmpty()
                    : target->count() > 0 && units->currentIndex() >= 0 &&
                      !device->text().trimmed().isEmpty() && !reading->text().trimmed().isEmpty()));
        };
        QObject::connect(device, &QLineEdit::textChanged, &dialog, [&](const QString&) { update_apply(); });
        QObject::connect(reading, &QLineEdit::textChanged, &dialog, [&](const QString&) { update_apply(); });
        QObject::connect(units, &QComboBox::currentIndexChanged, &dialog, [&](int) { update_apply(); });
        QObject::connect(tabs, &QTabWidget::currentChanged, &dialog, [&](int) { update_apply(); });
        QObject::connect(payload, &QPlainTextEdit::textChanged, &dialog, update_apply);
        update_apply();
        QObject::connect(load, &QPushButton::clicked, &dialog, [&] {
            const auto path = QFileDialog::getOpenFileName(
                &dialog, QStringLiteral("Load DISTO reading"), {},
                QStringLiteral("JSON files (*.json *.disto);;All files (*.*)"));
            if (path.isEmpty()) return;
            QFile file(path);
            if (!file.open(QIODevice::ReadOnly) || file.size() > 1024 * 1024) {
                status->setText(QStringLiteral("The DISTO file could not be read or is larger than 1 MiB."));
                return;
            }
            payload->setPlainText(QString::fromUtf8(file.readAll()));
            status->setText(QStringLiteral("Loaded. Review the target field before applying."));
        });
        QObject::connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
        QObject::connect(buttons->button(QDialogButtonBox::Apply), &QPushButton::clicked, &dialog, [&] {
            try {
                if (!sourceEditAuthorityUnchanged(authority)) {
                    status->setText(lastError());
                    return;
                }
                auto record = payload->toPlainText();
                if (tabs->currentIndex() == 0) {
                    DistoMeasurementRecord context{{1, 0}, new_id("measurement"),
                        target->currentData().toString().toStdString(), 0.0,
                        units->currentData().toString().toStdString(),
                        QDateTime::currentDateTimeUtc().toString(QStringLiteral("yyyy-MM-ddTHH:mm:ss'Z'")).toStdString(),
                        device->text().trimmed().toStdString(), "not-reported", {},
                        "Entered through the keyboard measurement dialog."};
                    const auto observation = parse_disto_keyboard_measurement(reading->text().toStdString(),
                        std::move(context), decimal->currentData().toString().at(0).toLatin1());
                    record = QString::fromStdString(disto_measurement_json(observation));
                }
                if (importDistoMeasurement(record, replace->isChecked())) dialog.accept();
                else status->setText(lastError());
            } catch (const std::exception& error) {
                status->setText(QString::fromUtf8(error.what()));
            }
        });
        QObject::connect(reading, &QLineEdit::returnPressed, &dialog, [&] {
            if (buttons->button(QDialogButtonBox::Apply)->isEnabled())
                buttons->button(QDialogButtonBox::Apply)->click();
        });
        dialog.exec();
    }

    void showAssistance() {
        QDialog dialog(owner);
        styleDialog(dialog);
        dialog.setObjectName(QStringLiteral("assistanceDialog"));
        dialog.setWindowTitle(QStringLiteral("Assistance"));
        dialog.setModal(true);
        dialog.resize(840, 640);

        auto* layout = new QVBoxLayout(&dialog);
        auto* enabled = new QCheckBox(QStringLiteral("Enable suggestions for this session"), &dialog);
        enabled->setChecked(m_assistance_session.enabled());
        enabled->setToolTip(QStringLiteral(
            "Assistance is optional and session-scoped. Every suggestion remains unverified until accepted."));
        layout->addWidget(enabled);

        auto* controls = new QHBoxLayout();
        auto* kind = new QComboBox(&dialog);
        kind->setObjectName(QStringLiteral("assistanceKind"));
        kind->addItem(QStringLiteral("Trace selected reference"),
                      static_cast<int>(AssistanceKind::tracing));
        kind->addItem(QStringLiteral("Trace detected edges"),
                      static_cast<int>(AssistanceKind::edge_tracing));
        kind->addItem(QStringLiteral("Extract explicit dimensions"),
                      static_cast<int>(AssistanceKind::dimension_extraction));
        kind->addItem(QStringLiteral("Place labels on named objects"),
                      static_cast<int>(AssistanceKind::label_placement));
        kind->addItem(QStringLiteral("Parse a command"),
                      static_cast<int>(AssistanceKind::natural_language));
        controls->addWidget(kind);
        auto* command = new QLineEdit(&dialog);
        command->setObjectName(QStringLiteral("assistanceCommand"));
        command->setPlaceholderText(m_metric_units
            ? QStringLiteral("label Entry at 1.25 m, 2.5 m")
            : QStringLiteral("label Entry at 8' 6\", 12'"));
        command->setToolTip(m_metric_units
            ? QStringLiteral("Bare lengths and coordinates use metres. Explicit units override the default. Example: draw rectangle 4 x 3.")
            : QStringLiteral("Bare lengths and coordinates use feet. Explicit units override the default. Example: draw rectangle 12 x 10."));
        command->setVisible(false);
        controls->addWidget(command, 1);
        auto* generate = new QPushButton(QStringLiteral("Generate suggestions"), &dialog);
        generate->setObjectName(QStringLiteral("assistanceGenerate"));
        controls->addWidget(generate);
        layout->addLayout(controls);

        auto* source_form = new QFormLayout;
        auto* reference_choice = new QComboBox(&dialog);
        reference_choice->setObjectName(QStringLiteral("assistanceReference"));
        auto* target_choice = new QComboBox(&dialog);
        target_choice->setObjectName(QStringLiteral("assistanceDimensionTarget"));
        auto* segment_choice = new QComboBox(&dialog);
        segment_choice->setObjectName(QStringLiteral("assistanceDimensionSegment"));
        auto* image_text = new QCheckBox(QStringLiteral("Recognize image text even when embedded text is available"), &dialog);
        image_text->setObjectName(QStringLiteral("assistanceRecognizeImage"));
        source_form->addRow(QStringLiteral("Reference plan"), reference_choice);
        source_form->addRow(QStringLiteral("Dimension target"), target_choice);
        source_form->addRow(QStringLiteral("Target edge"), segment_choice);
        source_form->addRow(image_text);
        layout->addLayout(source_form);
        target_choice->addItem(QStringLiteral("Choose a wall, area, or measured line…"), QString{});
        const auto source = authoringSnapshot();
        for (const auto& [id, entity] : source.entities()) {
            if (entity.type == "reference_asset") {
                reference_choice->addItem(QString::fromStdString(entity.properties.value("name", id)), id_from(id));
            } else if (entity.type == "wall") {
                try {
                    (void)resolve_dimension_wall_axis_owner(entity);
                    target_choice->addItem(QStringLiteral("Wall · %1").arg(
                        QString::fromStdString(entity.properties.value("name", id))), id_from(id));
                } catch (const std::exception&) { /* Unsupported physical walls cannot receive linked dimensions. */ }
            } else if (can_recognize_boundary_entity_type(entity.type) || entity.type == "measurement_linework") {
                try {
                    auto target = entity;
                    if (target.type != "measurement_linework" &&
                        inspect_boundary_entity_version(target).format == BoundaryEntityFormat::anonymous_legacy)
                        target = upgrade_legacy_boundary_entity(target);
                    (void)resolve_dimension_geometry_owner(target);
                    target_choice->addItem(QString::fromStdString(entity.properties.value("name", id)), id_from(id));
                } catch (const std::exception&) { /* Unavailable geometry cannot be an association target. */ }
            }
        }
        if (const auto selected = reference_choice->findData(m_selected_id); selected >= 0)
            reference_choice->setCurrentIndex(selected);
        if (const auto selected = target_choice->findData(m_selected_id); selected >= 0)
            target_choice->setCurrentIndex(selected);
        const auto populate_segments = [&] {
            segment_choice->clear();
            const auto snapshot = authoringSnapshot();
            const auto found = snapshot.entities().find(target_choice->currentData().toString().toStdString());
            if (found == snapshot.entities().end()) return;
            try {
                if (found->second.type == "wall") {
                    (void)resolve_dimension_wall_axis_owner(found->second);
                    return;
                }
                if (found->second.type != "measurement_linework" &&
                    inspect_boundary_entity_version(found->second).format == BoundaryEntityFormat::anonymous_legacy) {
                    segment_choice->addItem(QStringLiteral("First edge (legacy area)"), QString{});
                    return;
                }
                const auto geometry = resolve_dimension_geometry_owner(found->second);
                std::size_t number = 0;
                for (const auto& edge : geometry.segments)
                    segment_choice->addItem(QStringLiteral("Edge %1 · %2").arg(++number)
                        .arg(format_length(segment_length(edge.segment), m_metric_units)), id_from(edge.segment_id));
            } catch (const std::exception&) { /* Regeneration reports the unavailable target. */ }
        };
        QObject::connect(target_choice, &QComboBox::currentIndexChanged, &dialog, [&](int) { populate_segments(); });
        populate_segments();
        const auto show_reference_fields = [&] {
            const auto value = static_cast<AssistanceKind>(kind->currentData().toInt());
            const bool uses_reference = value == AssistanceKind::tracing || value == AssistanceKind::edge_tracing ||
                                        value == AssistanceKind::dimension_extraction;
            const bool dimensions = value == AssistanceKind::dimension_extraction;
            const auto show = [source_form](QWidget* field, bool visible) {
                field->setVisible(visible);
                if (auto* label = source_form->labelForField(field)) label->setVisible(visible);
            };
            const auto snapshot = authoringSnapshot();
            const auto target = snapshot.entities().find(target_choice->currentData().toString().toStdString());
            const bool wall_target = target != snapshot.entities().end() && target->second.type == "wall";
            show(reference_choice, uses_reference); show(target_choice, dimensions); show(segment_choice, dimensions && !wall_target);
            image_text->setVisible(dimensions);
        };
        QObject::connect(kind, &QComboBox::currentIndexChanged, &dialog, [&](int) { show_reference_fields(); });
        QObject::connect(target_choice, &QComboBox::currentIndexChanged, &dialog, [&](int) { show_reference_fields(); });
        show_reference_fields();

        auto* list = new QListWidget(&dialog);
        list->setObjectName(QStringLiteral("assistanceProposalList"));
        list->setSelectionMode(QAbstractItemView::SingleSelection);
        list->setMinimumHeight(64);
        list->setMaximumHeight(112);
        layout->addWidget(list);
        auto* review_canvas = new PlanCanvas(&dialog);
        review_canvas->setObjectName(QStringLiteral("assistanceReviewCanvas"));
        review_canvas->setMinimumHeight(260);
        review_canvas->setSnapEnabled(false);
        review_canvas->setOverviewMapEnabled(false);
        review_canvas->setSelectionTransformEnabled(false, false);
        review_canvas->setCanvasBackground(QColor("#ffffff"));
        new BoundaryPreviewFit(review_canvas);
        layout->addWidget(review_canvas, 1);
        auto* review_details = new QLabel(&dialog);
        review_details->setObjectName(QStringLiteral("assistanceReviewDetails"));
        review_details->setTextFormat(Qt::PlainText);
        review_details->setWordWrap(true);
        layout->addWidget(review_details);
        auto* status = new QLabel(&dialog);
        status->setWordWrap(true);
        status->setTextFormat(Qt::PlainText);
        status->setObjectName(QStringLiteral("assistanceStatus"));
        layout->addWidget(status);

        auto* buttons = new QHBoxLayout();
        auto* accept = new QPushButton(QStringLiteral("Accept selected"), &dialog);
        accept->setObjectName(QStringLiteral("assistanceAccept"));
        auto* close = new QPushButton(QStringLiteral("Close"), &dialog);
        close->setDefault(true);
        buttons->addStretch(1);
        buttons->addWidget(accept);
        buttons->addWidget(close);
        layout->addLayout(buttons);

        std::vector<AssistanceProposal> proposals;
        const auto show_proposal = [&] {
            review_canvas->setReferences({}); review_canvas->setEntities({}); review_canvas->setLabels({});
            review_details->clear(); accept->setEnabled(false);
            const auto* row = list->currentItem();
            if (!row) return;
            const auto index = row->data(Qt::UserRole).toInt();
            if (index < 0 || index >= static_cast<int>(proposals.size())) return;
            const auto& proposal = proposals[static_cast<std::size_t>(index)];
            accept->setEnabled(m_assistance_session.enabled());
            accept->setText(proposal.kind == AssistanceKind::dimension_extraction
                ? QStringLiteral("Add linked dimension") : QStringLiteral("Accept selected"));
            try {
                const auto preview_source = authoringSnapshot();
                const auto& arguments = proposal.preview.arguments;
                requireCurrentAssistanceSource(proposal, preview_source);
                const auto& binding = m_assistance_sources.at(proposal.id);
                const bool uses_reference = proposal.kind == AssistanceKind::tracing ||
                    proposal.kind == AssistanceKind::edge_tracing || proposal.kind == AssistanceKind::dimension_extraction;
                if ((proposal.kind == AssistanceKind::tracing || proposal.kind == AssistanceKind::edge_tracing) &&
                    !proposal.source.reference_id.empty()) {
                    SnapshotPlanSceneOptions options;
                    options.metric_units = m_metric_units;
                    PlanSceneCaches caches;
                    const auto scene = projectSnapshotPlanScene(preview_source, options, caches);
                    const auto reference = std::find_if(scene.references.begin(), scene.references.end(),
                        [&](const auto& image) { return image.id.toStdString() == proposal.source.reference_id; });
                    if (reference == scene.references.end())
                        throw std::invalid_argument("The reference preview is unavailable.");
                    review_canvas->setReferences({binding.site_plan
                        ? site_presented_canvas_reference(*reference,
                            resolve_site_presentation(preview_source, proposal.source.reference_id))
                        : *reference});
                    std::vector<CanvasEntity> contours;
                    const auto append_contour = [&](const json& points, const QString& id) {
                        CanvasEntity contour{id, QStringLiteral("boundary"), assistanceBoundary(points)};
                        contour.stroke_color = QColor("#1671f5");
                        if (binding.site_plan)
                            contour = site_presented_canvas_entity(contour, binding.destination_frame);
                        contours.push_back(std::move(contour));
                    };
                    append_contour(arguments.at("points"), id_from(proposal.id));
                    if (arguments.contains("holes")) {
                        const auto& holes = arguments.at("holes");
                        for (std::size_t index = 0; index < holes.size(); ++index)
                            append_contour(holes.at(index), id_from(proposal.id) +
                                QStringLiteral("-void-%1").arg(index + 1));
                    }
                    review_canvas->setEntities(std::move(contours));
                    review_canvas->fitView();
                } else if (uses_reference && !proposal.source.reference_id.empty()) {
                    const auto raster = decodeAssistanceReference(id_from(proposal.source.reference_id));
                    QImage source_image(static_cast<int>(raster.width), static_cast<int>(raster.height),
                                        QImage::Format_Grayscale8);
                    if (source_image.isNull()) throw std::invalid_argument("The reference preview is unavailable.");
                    for (std::size_t y = 0; y < raster.height; ++y)
                        std::copy_n(raster.luminance.data() + y * raster.width, raster.width,
                                    source_image.scanLine(static_cast<int>(y)));
                    CanvasReference image{QStringLiteral("assistance-source"), std::move(source_image)};
                    image.metres_per_source_unit = 1.0;
                    review_canvas->setReferences({image});
                    const auto w = double(image.image.width()), h = double(image.image.height());
                    const auto& rectangle = proposal.source;
                    const AssistanceEngineOptions preview_options{1.0, {}, 0.0, 1.0, true};
                    const auto a = assistance_source_point_to_model({rectangle.x * w, rectangle.y * h},
                        raster.width, raster.height, preview_options);
                    const auto b = assistance_source_point_to_model(
                        {(rectangle.x + rectangle.width) * w, (rectangle.y + rectangle.height) * h},
                        raster.width, raster.height, preview_options);
                    CanvasEntity region{QStringLiteral("assistance-region"), QStringLiteral("boundary"),
                        {{{a.x,a.y},{b.x,a.y},0},{{b.x,a.y},{b.x,b.y},0},
                         {{b.x,b.y},{a.x,b.y},0},{{a.x,b.y},{a.x,a.y},0}}};
                    region.stroke_color = QColor("#1671f5");
                    region.filled = true; region.fill_color = QColor("#1671f5"); region.fill_opacity = 0.08;
                    review_canvas->setEntities({region}); review_canvas->fitView();
                }
                if (proposal.kind == AssistanceKind::dimension_extraction) {
                    const bool wall_target = proposal.preview.command_type == "add_wall_dimension_suggestion";
                    const auto target = proposal.preview.arguments.at(wall_target ? "target_wall_id" : "target_boundary_id").get<std::string>();
                    auto owner = preview_source.entities().at(target);
                    Segment target_segment;
                    if (wall_target) target_segment = resolve_dimension_wall_axis_owner(owner);
                    else {
                    if (owner.type != "measurement_linework" &&
                        inspect_boundary_entity_version(owner).format == BoundaryEntityFormat::anonymous_legacy)
                        owner = upgrade_legacy_boundary_entity(owner);
                    const auto geometry = resolve_dimension_geometry_owner(owner);
                    auto id = proposal.preview.arguments.value("target_segment_id", std::string{});
                    if (id.empty()) id = geometry.segments.front().segment_id;
                    const auto edge = std::find_if(geometry.segments.begin(), geometry.segments.end(),
                        [&](const auto& item) { return item.segment_id == id; });
                    if (edge == geometry.segments.end()) throw std::invalid_argument("The target edge is unavailable.");
                    target_segment = edge->segment;
                    }
                    review_details->setText(QStringLiteral("Recognized: %1 (%2%)\nTarget: %3 · %4\n"
                        "The linked dimension displays the drawing measurement. Recognized text is retained as its source note.")
                        .arg(QString::fromStdString(proposal.source.original_text))
                        .arg(proposal.source.confidence * 100.0, 0, 'f', 0)
                        .arg(QString::fromStdString(owner.properties.value("name", owner.id)),
                             format_length(segment_length(target_segment), m_metric_units)));
                } else if (proposal.kind == AssistanceKind::tracing || proposal.kind == AssistanceKind::edge_tracing) {
                    const auto void_count = arguments.contains("holes") ? arguments.at("holes").size() : 0;
                    review_details->setText(QStringLiteral("Proposed outline: %1 edges, %2 interior voids\nSource: %3 (%4%)")
                        .arg(arguments.at("points").size()).arg(void_count)
                        .arg(QString::fromStdString(preview_source.entities().at(proposal.source.reference_id)
                            .properties.value("name", proposal.source.reference_id)))
                        .arg(proposal.source.confidence * 100.0, 0, 'f', 0));
                } else if (proposal.preview.command_type == "add_label") {
                    const auto position = read_point(arguments.at("position"));
                    if (!position) throw std::invalid_argument("The proposed label position is invalid.");
                    CanvasLabel label{id_from(proposal.id), *position,
                        QString::fromStdString(arguments.at("content").get<std::string>())};
                    label.color = QColor("#111111");
                    label.paper_height_mm = 3.0;
                    if (binding.site_plan)
                        label = site_presented_canvas_label(label, binding.destination_frame);
                    review_canvas->setLabels({label});
                    QString context;
                    if (arguments.contains("anchor_entity_id")) {
                        const auto anchor_id = arguments.at("anchor_entity_id").get<std::string>();
                        const auto& anchor = preview_source.entities().at(anchor_id);
                        context = QStringLiteral("\nNamed object: %1").arg(
                            QString::fromStdString(anchor.properties.value("name", anchor_id)));
                        SnapshotPlanSceneOptions options;
                        options.metric_units = m_metric_units;
                        PlanSceneCaches caches;
                        auto scene = projectSnapshotPlanScene(preview_source, options, caches);
                        std::erase_if(scene.all_geometry, [&](const auto& geometry) {
                            return geometry.id.toStdString() != anchor_id;
                        });
                        if (binding.site_plan) {
                            const auto frame = resolve_site_presentation(preview_source, anchor_id);
                            for (auto& geometry : scene.all_geometry)
                                geometry = site_presented_canvas_entity(geometry, frame);
                        }
                        review_canvas->setEntities(std::move(scene.all_geometry));
                    }
                    review_canvas->fitView();
                    review_details->setText(QStringLiteral("Add label: %1\nModel position: %2, %3%4\nSource: %5 (%6%)")
                        .arg(label.text, format_length(position->x, m_metric_units),
                             format_length(position->y, m_metric_units), context,
                             QString::fromStdString(proposal.source.original_text))
                        .arg(proposal.source.confidence * 100.0, 0, 'f', 0));
                } else if (proposal.kind == AssistanceKind::natural_language &&
                           proposal.preview.command_type == "add_boundary") {
                    const auto boundary = assistanceBoundary(arguments.at("points"));
                    CanvasEntity geometry{id_from(proposal.id), QStringLiteral("boundary"), boundary};
                    geometry.stroke_color = QColor("#1671f5");
                    if (binding.site_plan)
                        geometry = site_presented_canvas_entity(geometry, binding.destination_frame);
                    review_canvas->setEntities({geometry}); review_canvas->fitView();
                    review_details->setText(QStringLiteral("Draw rectangle: %1 × %2\nClassification: %3\nSource: %4 (%5%)")
                        .arg(format_length(arguments.at("width_metres").get<double>(), m_metric_units),
                             format_length(arguments.at("height_metres").get<double>(), m_metric_units),
                             QString::fromStdString(arguments.at("classification").get<std::string>()),
                             QString::fromStdString(proposal.source.original_text))
                        .arg(proposal.source.confidence * 100.0, 0, 'f', 0));
                } else if (proposal.preview.command_type == "set_workspace") {
                    review_details->setText(QStringLiteral("Change workspace to %1.\nSource: %2 (%3%)")
                        .arg(QString::fromStdString(arguments.at("workspace").get<std::string>()),
                             QString::fromStdString(proposal.source.original_text))
                        .arg(proposal.source.confidence * 100.0, 0, 'f', 0));
                } else {
                    review_details->setText(QStringLiteral("Source: %1 · confidence %2%").arg(
                        QString::fromStdString(proposal.source.original_text.empty()
                            ? proposal.source.reference_id : proposal.source.original_text))
                        .arg(proposal.source.confidence * 100.0, 0, 'f', 0));
                }
                if (binding.drawing_context) {
                    const auto& context = *binding.drawing_context;
                    const auto owner_name = [&](const std::string& id) {
                        const auto& entity = preview_source.entities().at(id);
                        return QString::fromStdString(entity.properties.value("name", id));
                    };
                    review_details->setText(review_details->text() +
                        QStringLiteral("\nDestination: %1 · %2 · %3")
                            .arg(owner_name(context.building_id), owner_name(context.floor_id),
                                 owner_name(context.layer_id)));
                }
            } catch (const std::exception& error) {
                review_details->setText(QString::fromUtf8(error.what())); accept->setEnabled(false);
            }
        };
        QObject::connect(list, &QListWidget::currentRowChanged, &dialog, [&](int) { show_proposal(); });
        const auto kind_name = [](AssistanceKind value) {
            switch (value) {
            case AssistanceKind::tracing: return QStringLiteral("tracing");
            case AssistanceKind::edge_tracing: return QStringLiteral("edge tracing");
            case AssistanceKind::dimension_extraction: return QStringLiteral("dimensions");
            case AssistanceKind::label_placement: return QStringLiteral("labels");
            case AssistanceKind::natural_language: return QStringLiteral("command");
            }
            return QStringLiteral("unknown");
        };
        const auto repopulate = [&] {
            list->clear();
            const auto source_names = authoringSnapshot();
            for (std::size_t index = 0; index < proposals.size(); ++index) {
                const auto& item = proposals[index];
                auto source_name = item.source.original_text;
                if (source_name.empty()) {
                    const auto owner = source_names.entities().find(item.source.reference_id);
                    source_name = owner == source_names.entities().end() ? item.source.reference_id
                        : owner->second.properties.value("name", item.source.reference_id);
                }
                auto* row = new QListWidgetItem(
                    QStringLiteral("Unverified · %1 · %2 · %3%")
                        .arg(kind_name(item.kind), QString::fromStdString(source_name))
                        .arg(item.source.confidence * 100.0, 0, 'f', 0), list);
                row->setData(Qt::UserRole, static_cast<int>(index));
                row->setToolTip(QStringLiteral("Source: %1\nAffected: %2")
                    .arg(QString::fromStdString(source_name),
                         QString::fromStdString(item.preview.affected_entity_ids.empty()
                                                     ? std::string{} : item.preview.affected_entity_ids.front())));
            }
            if (list->count() > 0) list->setCurrentRow(0);
            else show_proposal();
        };
        std::uint64_t suggestion_context_serial = 0;
        const auto invalidate_suggestions = [&] {
            ++suggestion_context_serial;
            const bool had_suggestions = !proposals.empty();
            proposals.clear();
            repopulate();
            if (had_suggestions) status->setText(QStringLiteral("Options changed. Generate suggestions again."));
        };
        for (auto* choice : {kind, reference_choice, target_choice, segment_choice})
            QObject::connect(choice, &QComboBox::currentIndexChanged, &dialog,
                             [&](int) { invalidate_suggestions(); });
        QObject::connect(image_text, &QCheckBox::toggled, &dialog,
                         [&](bool) { invalidate_suggestions(); });
        QObject::connect(command, &QLineEdit::textChanged, &dialog,
                         [&](const QString&) { invalidate_suggestions(); });
        QObject::connect(enabled, &QCheckBox::toggled, &dialog,
                         [&](bool checked) { setAssistanceEnabled(checked); show_proposal(); });
        QObject::connect(kind, &QComboBox::currentIndexChanged, &dialog, [kind, command](int index) {
            const auto value = static_cast<AssistanceKind>(kind->itemData(index).toInt());
            command->setVisible(value == AssistanceKind::natural_language);
        });
        QObject::connect(generate, &QPushButton::clicked, &dialog, [&] {
            if (!generate->isEnabled()) return;
            generate->setEnabled(false);
            struct GenerateGuard { QPushButton* button; ~GenerateGuard() { button->setEnabled(true); } } guard{generate};
            const auto generation_context_serial = suggestion_context_serial;
            proposals.clear();
            repopulate();
            const auto value = static_cast<AssistanceKind>(kind->currentData().toInt());
            if (value == AssistanceKind::natural_language) {
                proposals = parseAssistanceCommand(command->text());
            } else if (value == AssistanceKind::label_placement) {
                proposals = suggestLabelAssistance();
            } else {
                const auto reference = reference_choice->currentData().toString();
                if (reference.isEmpty()) {
                    status->setText(QStringLiteral("Select or import a reference image first."));
                    repopulate();
                    return;
                }
                if (value == AssistanceKind::dimension_extraction && target_choice->currentData().toString().isEmpty()) {
                    status->setText(QStringLiteral("Choose the wall, area, or measured line to associate with the recognized text."));
                    repopulate(); return;
                }
                proposals = suggestReferenceAssistance(reference, value, target_choice->currentData().toString(),
                    segment_choice->currentData().toString(), image_text->isChecked());
            }
            if (generation_context_serial != suggestion_context_serial) {
                proposals.clear(); repopulate();
                status->setText(QStringLiteral("Options changed while suggestions were generated. Generate them again."));
                return;
            }
            repopulate();
            if (proposals.empty()) {
                const auto error = lastError();
                status->setText(error.isEmpty() ? QStringLiteral("No suggestions were produced.") : error);
            } else {
                status->setText(QStringLiteral(
                    "Suggestions are provisional. Review the source and preview before accepting."));
            }
        });
        QObject::connect(accept, &QPushButton::clicked, &dialog, [&] {
            const auto row = list->currentItem();
            if (!row) {
                status->setText(QStringLiteral("Choose a suggestion first."));
                return;
            }
            const auto index = row->data(Qt::UserRole).toInt();
            if (index < 0 || index >= static_cast<int>(proposals.size())) {
                status->setText(QStringLiteral("The suggestion list is stale. Generate it again."));
                return;
            }
            const auto before = authoringSnapshot();
            const auto workspace = m_workspace;
            const auto context = captureSourceEditAuthority(before);
            const bool site_plan = siteCanvas(m_architecturalCanvas);
            if (acceptAssistanceProposal(proposals[static_cast<std::size_t>(index)])) {
                proposals.erase(proposals.begin() + index);
                const auto after = authoringSnapshot();
                if (m_workspace == workspace && after.document_id() == before.document_id() &&
                    m_document == context.context.document && m_active_layer_id == context.context.layer_id &&
                    m_metric_units == context.context.metric_units && m_view_filter == context.visibility &&
                    m_architectural_view_kind == context.view_kind && m_active_named_view == context.named_view &&
                    m_active_named_view_owner == context.named_view_owner &&
                    site_plan == siteCanvas(m_architecturalCanvas) &&
                    after.revision() == before.revision() + 1) {
                    const auto digest = document_snapshot_digest(after);
                    for (auto& proposal : proposals) {
                        proposal.preview.arguments["source_document_digest"] = digest;
                        proposal.preview.arguments["source_workspace"] = static_cast<int>(m_workspace);
                        auto& binding = m_assistance_sources.at(proposal.id);
                        binding.authority = captureSourceEditAuthority(after);
                        binding.proposal = encode_assistance_proposal(proposal);
                    }
                } else proposals.clear();
                repopulate();
                status->setText(QStringLiteral("Suggestion applied."));
            } else {
                status->setText(lastError());
            }
            });
            QObject::connect(close, &QPushButton::clicked, &dialog, &QDialog::reject);
            dialog.exec();
    }

